# BFS from all 0s to see connectivity
from collections import deque

def get_connectivity_to_3(grid):
    """Returns a set of 0-cells that can reach a 3 through only 0s"""
    R, C = len(grid), len(grid[0])
    can_reach = set()

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 3:
                visited = set()
                queue = deque([(r,c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if grid[nr][nc] == 0 and (nr, nc) not in visited:
                                    can_reach.add((nr, nc))
                                    queue.append((nr, nc))
    return can_reach

