from collections import deque

def test_propagation(grid_in, grid_out):
    """Test: find 2x2 blocks, fill them, then propagate adjacent neighbors"""
    R, C = len(grid_in), len(grid_in[0])

    # Step 1: Find all 2x2 blocks of 0s in input
    filled = [[float('inf')]*C for _ in range(R)]  # 8: filled by 2x2 rule
    propagate = [[float('inf')]*C for _ in range(R)]  # 1: propagated from neighbor

    # Mark 2x2 blocks
    for r in range(R-1):
        for c in range(C-1):
            if (grid_in[r][c] == 0 and grid_in[r][c+1] == 0 and 
                grid_in[r+1][c] == 0 and grid_in[r+1][c+1] == 0):
                filled[r][c] = 8  # 2x1
                filled[r][c+1] = 8
                filled[r+1][c] = 8
                filled[r+1][c+1] = 8

    # Step 2: Propagate from 2x2 blocks through adjacent 0s
    queue = deque()
    for r in range(R):
        for c in range(C):
            if filled[r][c] == 8:
                queue.append((r,c))
                propagate[r][c] = 1

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and grid_in[nr][nc] == 0 and propagate[nr][nc] == float('inf'):
                propagate[nr][nc] = 1
                queue.append((nr, nc))

    # Step 3: Compare with actual output
    correct = 0
    wrong = 0
    mismatches = []

    for r in range(R):
        for c in range(C):
            in_val = grid_in[r][c]
            if in_val == 0:
                predicted = 3 if filled[r][c] == 8 or propagate[r][c] == 1 else 0
                actual = grid_out[r][c]
                if predicted == actual:
                    correct += 1
                else:
                    wrong += 1
                    mismatches.append(((r,c), in_val, actual, predicted))
            elif in_val == 3:
                actual = grid_out[r][c]
                if actual == 3:
                    correct += 1
                else:
                    wrong += 1
                    mismatches.append(((r,c), in_val, actual, 3))
            else:  # background 5
                actual = grid_out[r][c]
                if actual == 5:
                    correct += 1
                else:
                    wrong += 1
                    mismatches.append(((r,c), in_val, actual, 5))

    return correct, wrong, mismatches

