# New hypothesis: the rule is to mark the CORNERS of all 0-rectangles
# A rectangle is defined by its top-left and bottom-right corners
# For a rectangle of 0s, mark its 4 corners as 3

def transform_rect_corners(grid):
    R = len(grid)
    C = len(grid[0])
    result = [list(row) for row in grid]

    # Find all rectangles of 0s (using top-left and bottom-right boundaries)
    for r1 in range(R):
        for c1 in range(C):
            if grid[r1][c1] == 0:
                # Extend to find rectangle
                for r2 in range(r1+1, R):
                    for c2 in range(c1+1, C):
                        # Check if all cells in this rectangle are 0
                        is_rect = True
                        for rr in range(r1, r2+1):
                            for cc in range(c1, c2+1):
                                if grid[rr][cc] != 0:
                                    is_rect = False
                                    break
                            if not is_rect:
                                break

                        if is_rect:
                            # Mark corners
                            if grid[r1][c1] != 0:
                                result[r1][c1] = 3
                            if grid[r1][c2] != 0:
                                result[r1][c2] = 3
                            if grid[r2][c1] != 0:
                                result[r2][c1] = 3
                            if grid[r2][c2] != 0:
                                result[r2][c2] = 3

    return result

